INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1293714-mis301', 'stk-user5374', 'MIS 301', 'info', '{"desc": "http://skfupm.kfupm.edu.sa/vb/showthread.php?t=40097\n\nMIS 301\n\nاشوف المادة سهلة ، وهي المادة اللي راح تفهمك وش يعني تخصصMIS\n\nالمادة تعطي فكرة عامة عن التخصص ، وكلها تكلّم عن system development life cycle المتكونة من خمس مراحل تاخذها بالتفصيل في هالمادة وطبعا فيها بروجكت ، تسوي نظام لمحل او شركة المهم تسوي نظام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-301-business-systems-analysis-design-i/120974/4", "user": "user5374", "ts": 1385370058000, "tid": 120974, "pn": 4}}', 1385370058000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1487821-mis301', 'stk-h-a-g', 'MIS 301', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالكورس يعتبر هو وMIS311 اهم كورسين في نظري في التخصص. الكورس يدخلك عالم الـMIS وما راح تفهم التخصص زين الا اذا اخذته. الكورس يتكلم عن الجزء النظري من تطوير الانظمة الالكترونية Software Development Life Cycle بدءً بدراسة جدوى النظام مرورا ببناءه وينتهي بتركيبه. الكورس ما بيدخل في الاشياء التكنيكال كثير وراح يركز أكثر على الجانب النظري. واللاب اللي فيه يكون عن الـUse Case والـ Feasibility و شوي ERD يعني مو ثقيل وما فيه اشياء تكنيكال كثير.\n\nالمواضيع التي يغطيها المقرر\n\nالكورس يتكلم عن ال Software Development Life Cycle وهي :\n\nPlanning.\nAnalysis.\nDesign.\nImplementation: ما يركز الكورس هنا لان هذي المرحلة لها كورس لحالها اللي هو MIS311.\nMaintenance.\nالكتاب المستخدم للمقرر\n\nما كنت افتح الكتاب كثير مع الدكتور النهاري وكنت اذاكر السلايدات والـTB.\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nأهم شيء الفهم والتركيز مع الدكتور في الكلاس واللاب ومراجعة بسيطة قبل الكويزات.\n\nمدى فائدته في الناحية التطبيقية\n\nمدخل لعالم الـMIS ويعلمك الاساسيات في التخصص ويعتبر حجر اساس لبقية كورسات الـMIS.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-301-business-systems-analysis-design-i/120974/5", "user": "H-A-G", "ts": 1518614152000, "tid": 120974, "pn": 5}}', 1518614152000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p27214-mis301', 'stk-c.i.m', 'MIS 301', 'info', '{"desc": "اخوي advisor انا خذت هذي الماده الترم اللي راح مع شهيد الاسلام…وفي اول كلاس سأل من فيه تخصصه محاسبه\n\nقلت انا … وقال يمكن الماده ماتصير ريكوستد عللى طلاب المحاسبه…\n\nو بعد الكلاس رحت له لمكتبه وسألته يعني احذف هذي الماده والا اخليها…\n\nقال لي : خلها الكلام ما تأكد الا الحين(هذاالكلام الترم اللي راح) لانا نجتمع مع مدرسين\n\nال ام اي اس وبنشوف وش نسوي… هذا كلامه لي\n\nاما اذا كانت الماده الكتف و نيتك تاخذها … فنصيحتي لك (((( وخـــر عــنــهـــا))))\n\nالماد مش صعبه بالعكس كتابها سلس و سهل في بعض الشباتر…\n\nلكن فيها مشكله كبيييره الا وهي البروجكت بروجرس بروجكت يعني تسلم اربع بروجكتات\n\nو البروجكت لازم تسوي بضه في الاكسيس والفيزبل انالست…\n\nوالماده ماده حفظ…\n\nو اتمنى اني افدتك\n\nو تحياتي لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-301/23377/6", "user": "c.i.m", "ts": 1058917556000, "tid": 23377, "pn": 6}}', 1058917556000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousefli-mis301', 'stk-yousefli', 'MIS 301', 'doc', '{"docs": [{"id": "stk-dr-f98421", "n": "Dr. Amine Nehari Talet", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 301 - 191\nالكرف:\nالمادة بتصير غثيثة للامانة لان الدكتور يتطلب كثير وتتعب طول الترم\nاكثر مادة شلت همها هالترم اهي لان ما تدري شوضعك وتضيع في اشياء كثيرة\nبسبة الدكتور احيانا يشرح شيء سهل ولما يعطيك واجب شيء ثاني صعب بحيث تتعب وانت تحل\n+ لا تنس كل شيء تسويه للمجموعة حطه ف ملف عشان انه الريبورت يبي كل شيء فسهلوا العملية عليكم من البداية\nوشوف الريبورت وش طريقته وجهزوه مو مثلنا انتكبنا بسبة انفجعا بالتعقيدات\n\nالتحضير :\nيومي وما يحب احد يتأخر حاول في البداية تحضر مبكر بعدين شوي يصير الوضع ايزي\nوعليه درجات لا تضيعها شيك السيلابوس\n\nطريقة الشرح :\nيفتح السلايدات ويشرح منها. الدكتور يعامل الطلاب باحترام وما عنده مشكلة يعيد اكثر من مرة اذا احد مافهم لكن احيانا يفصل عليك شوي لكن تحمله واحيانا ياخذ السؤال طول الترم. يحب انك تكون فاهم ومشارك معاه.\nالدكتور منظم ويحب تمشي معاه step by step لكن احيانا تنفجع في اشياء ما شرحها او مر عليها مرور الكرام وتجيك رتن.\nعيبه طبعا انه يشرح شيء ويطلب شيء ثاني فلازم تسوي كل شيء ورح له الاوفيس\nوالاسايمنتات طلبوه على الحل يطلب منك شيء وما يعطيك حله !\nفمن بداية الاسابيع قولوا له نبي الحل خلوه يشد هذي معضلة انه يخليك تحل شيء\nوما يعلمك صح ولا غلط ولما تسئله يقولك انا مشغول ! ومدري وش لكن لو كلمتوه من البداية بيساعدكم\n\nالكويزات :\nصح وغلط واختيارات وسؤال رتن وسؤال بونص\nطبعا الاختيارات\nطبعا فيه بعضها من التي بي وبعضها لا ! بعضها يختبر علمك\nاما اسئلة الرتن من الكتاب اخر كل شابتر بتحصل اسئلة !\nمره جاب سؤال من التي بي رتن !\nالبونص مو كثير عليه ف اسحب عليه لين تخلص الباقي !\nطلبوه الحل هم هنا ! لان احيانا تنعاد في الميجر نفس الفقرات فلو ما حليته هناك\nمراح تحله في الميجر\n\nالاسايمنت:\n\nجمع بونصات بحيث ترفع قبل كل لاب وتحاول تحل السؤال جمع لك لا تضيعهم لو تسلك المهم تحاول\nحرام تطيرها من يدك\n\nالمياجر:\nمتوسطة ونصها تقريبا خيارات وترو فولس وسؤال عملي وسؤال رتن وبونص. وغالبا يكون فيه سؤال ولا سؤالين بونص.\nالبونص مثل م قلت خله اخر شيء لا تنتكب\n\nالفاينلات :\n\nترمنا كان الفاينل سهل الى متوسط\nلكن مشكلته بالتصحيح ما ادري كيف يصحح\nالمهم انه بتاخذ القريد اللي اهو يحس انك تستحقه لو انت تستحق مثلا B\nواهو يشوف تستاهل اعلى بتاخذه لكن لو اقل هم راح ينزلك او يدقق\nففيها ظلم السالفة\n\nالتصحيح:\n\nانا برأيي اشوفه نوعا ما يعني يبي احيانا نفس المكتوب ف الكتاب او شيء كذا و\nودقيق واحيانا ينقصك وانت تستحق اكثر لكن نفس ما قلت لك راح تاخذ اللي يشوفه اهو انت تستحقه\nوتبين الكلام بعد الفاينل\nA شبه مستحيله عنده لكن b+ فيه في ترمنا ناس خذوها برأيه الخاص اهو\n\nراجعته بالكويز طلع غلطان وعطاني حقي لكن شاف سبلنق غلط خصم نص ما خلاها في خاطره، ترى احنا اوادم مو الة\nوخويي منقصه في الميجر ومعطيه ٠ واهو كان حاله بالضبط عدل\nراجعه وعطاه درجتين من ٤ !!! ظالم\n\nالبروجكت:\n\nاشتغلوا عليه صح\nسوينا كل شيء مع البونص وقالنا انتوا افضل ناس والخخ وما عطانا ١٥ من ١٥ ! ع رغم ان احنا مسوين بونص\nهذي ظلمنا فيها شدينا انفسنا وسوينا شيء جدا جبار لكن الدكتور مثل ما قلت لكم الكمال لله نظريته!\nلكن اخذوا قريد كويس اهو الشيء الوحيد اللي نفعنا كلنا وخلانا ناخذ قريد كويس\n\nالمصادر عندك للمذاكرة:\nالسلايدات ماهي سيئة لكن الكتاب مره ممتاز واسئلته اللي اخره تجي في الاختبارات رتن\ntb لان يجيب منه احيانا ويختبر فهمك ونادر يجيب من الرتن من tb لكن الفاينل جاب لنا اخر سؤال فان\n\nالقريد النهائي:\nB\n\nالصوت:\nعالي وواضح.\n\nإضافات :\n\nالدكتور كويس وينصحك ولما تسئله سؤال كذا جاء في بالك طول الترم يعيده على نقاط كثيره مو تفهيم لكن ما ينسى ماشاء الله عليه لكن يحسفك احيانا ويضل يعيد ويزيد، ولو مسك عليك غلط يضل كل كلاس يعيده مثلا انا عندي مشكلة بسبلق كل كلاس يمشي ويعطيني تهزيء ترى رافع واجب انا وسويت اللي علي وغلطت بحرف قالي تعني كلمة ثانيه وووووووووو ويعيد كل كلاس، لكن لا تحاول تشكك في معلوماته حتى لو كان مخطئ أو تراجع وراه في التصحيح لانه يزعل فانا رحت له اخر الترم وشفت كويزاتي وعدل لي قبل الفاينل والفاينل باقي لي درجة على القريد اللي بعده وانا عارف اني استحقها وحليت صح لكن نقصني وما عطاني القريد اللي بعده فلو رايح له في الفاينل ممكن خذت قريد اعلى فلو انت معيد لا لكن لو حال زين رح! وشوف يعني لانه ممكن ظالمك لكن لو انت مزحف نفس ما قلت احيانا ممكن يشوف تستحق ويعطيك شوي او يسلك. ونهاية السمستر يحذف اسوأ كويز او كويزين اذا بروجكت حقكم كويس. وما يدفك للA وممكن يعطيك مثل ماقلت لكم لو يشوف انك تستحق القريد اللي بعده.\nالدكتور يهتم بشكل كبير في البروجكت وممكن في النهاية يطلب منك شي ما طلبه منك في البداية وانتبهوا حق الريبورت تراه دقيق فيه تأكدوا كل ما تخلصون شيء تحطونه وسئلوه عنه كيف شكله والخخ وروحوا له قبل ما ترفعونه حبيب بيعلمكم وش اغلاطكم المجموعة الثانية ما راحو ويوم العرض اكلهم اكال لانه ممكن حلك صح\nلكن اهو يبي حل معين فلو رحت له بيعلمك، مشكلته انه عنده حل فراسه انرسم ف يبي بطريقه معينه لكل شيء فتأكدوا.\nوالكتور زين بشكل عام لكن لو يعطي الحلول ويشيل فكرة A للرب ويخلي المواضيع مو شخصية كل شيء تمام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518387-mis301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-amine-nehari-talet/98421/4", "user": "yousefli", "ts": 1577469638000, "tid": 98421, "pn": 4}}]}', 1577469638000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-mis301', 'stk-sadguts', 'MIS 301', 'doc', '{"docs": [{"id": "stk-dr-f98421", "n": "Dr. Amine Nehari Talet", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS301- 211\nالتحضير : بالبداية لكن مايدقق عالتاخير\nطريقة الشرح : الدكتور يغطي كل السلايدات والافكار الي فيها ويحب يضيف اشياء من خبرته، توفق في شرح متيريل المادة لكن شرح اللاب ماكان واضح وخصوصا في relational data model ورسم الدايقرامز. للامانة الدكتور يبذل جهده وكان يقرا التقييمات ويحاول يعدل طريقة شرحه\nاسايمنت اللاب: كانت اصعب من التمارين الي نحلها باللاب بمراحل ومو هذي المشكلة، المشكلة ان تصحيح الدكتور غريب في اللابات ونادرا ماكان يعطي فل او قريب الفل\nالكويزات : متوسطة وكان يجيب رتن\nالميد: كان مليان تركات لكن مقدور عليه واسئلة الريتن كانت طويلة وتصحيح الدكتور كان معقد (لازم تشرح الفكره زيييييييييييييين وبالتفاصيل ولا رح تنقص)\nالفاينل: كان غريب وجاب لنا اسئلة من مادة ثانية (فيه اسئلة برى المنهج ونبهنا الدكتورعلى اكثر من سؤال وحذفه)\nإضافات : الدكتور نهاري طريقته انه مايوضح كثير ولازم تبذل جهدك معه وتقرا الكتاب وخصوصا في البروجكت لازم تساله عن كل تفصيل صغير. الدكتور يحب الي يتعب معاه ويشتغل لاتهتم للكلام السلبي والي تسمعه عنه سوي الي يقولك عليه والي تتعلمه في الكتاب واذا ماعرفت شيء معين اساله وبيوضح لك كل شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533781-mis301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-amine-nehari-talet/98421/5", "user": "SadGuts", "ts": 1645339750000, "tid": 98421, "pn": 5}}]}', 1645339750000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5877-mis301', 'stk-user5877', 'MIS 301', 'doc', '{"docs": [{"id": "stk-dr-f107053", "n": "Dr. Yaser Mowafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا راح اتكلم بالنسبه لماده mis 301\nصراحه من اسوء المدرسين الي مروا علي و بالنسبه لماده تعتبر ماده تخصصي كرهني فيها لانه يتكلم في شيئ والكتاب يتكلم في شيئ ثاني وبعدين يجيب اسئله من الكتاب انت اصلا مو فاهمه عدل\nطريقه شرحه سيئه بالسلايدات ولا يتعب نفسه يستخدم الصبوره يشرح كيف يصير الدزاين الا بعد ما كلمناه نهايه السمستر\nالتحضير بدايه كل كلاس بس كان ما يهتم فيه كثير\nالمياجر نصف خيارات ونص مقاليه\nمثل ماقالوا الشباب الماده راح تكون سلف ستدي ولا تطلع بقريد منها بس مالك الا خشمك ولو عوج لانها ماده تخصص ومافي الا هو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p859468-mis301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yaser-mowafi/107053/6", "user": "user5877", "ts": 1309107423000, "tid": 107053, "pn": 6}}]}', 1309107423000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
